function services(){return `<section class="passport-invite"><div><span class="eyebrow">THE dp PASSPORT</span><h2>هر لباس، یک شناسنامه.</h2><p>با شناسه روی لباس، مشخصات ثبت‌شده آن را در dp ببینید.</p></div>${link("#/verify","استعلام محصول")}</section><section class="service-section"><a class="service-item" href="#/guide"><span>01</span><div><h3>اندازه‌ای که به شما می‌آید</h3><p>پیش از انتخاب، راهنمای اندازه و سایز را ببینید.</p></div></a><a class="service-item" href="#/guide?tab=order"><span>02</span><div><h3>انتخاب شما، تأیید با dp</h3><p>درخواست ثبت می‌شود؛ جزئیات پیش از نهایی شدن هماهنگ می‌شوند.</p></div></a><a class="service-item" href="#/contact"><span>03</span><div><h3>از نزدیک، کنار شما</h3><p>فروشگاه حضوری dp، بخشی از تجربه آشنایی با برند.</p></div></a></section>`}
function shop(params,isFavorites=false){const col=params.get('collection');const type=params.get('type')||'';const color=params.get('color')||'';const size=params.get('size')||'';const sort=params.get('sort')||'featured';const q=params.get('q')||'';let list=products.filter(p=>(!isFavorites||favorites.includes(p.id))&&(!collections[col]||p.collections.includes(col))&&(!type||p.type===type)&&(!size||p.sizes.includes(size))&&(!color||(color==='light'?p.color==='ivory':p.color===color))&&(!q||[p.name,p.subtitle,p.id,p.id.replace("NY-","DP-"),colors[p.color].name].join(' ').toLowerCase().includes(q.toLowerCase())));if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);const title=isFavorites?'انتخاب‌های نشان‌شده':collections[col]?.name||'جهان پیراهن‌تنبان dp';return `<section class="page-head catalog-head">${crumbs(title)}<span class="eyebrow">${collections[col]?.en||'EXPLORE dp'}</span><h1>${title}</h1><p>${isFavorites?'مدل‌هایی که برای دوباره دیدن کنار گذاشته‌اید.':(col==='signature'?'فرم آشنا و نقش‌های ظریف؛ انتخابی از مجموعه اصالت dp.':col==='royal'?'سبز رویال در گفت‌وگو با رنگ‌های روشن.':'از فرم کلی تا ظرافت یخن؛ انتخابی نزدیک به سلیقه شما.')}</p>${!isFavorites?`<nav class="collection-tabs" aria-label="مجموعه‌ها">${[['','همه مدل‌ها'],['signature','اصالت'],['royal','سبزِ ماندگار']].map(([v,t])=>`<a class="${(col||'')===v?'active':''}" href="#/shop${v?'?collection='+v:''}">${t}</a>`).join('')}</nav>`:''}</section><section class="section catalog-section">${q?`<p class="search-query">نتیجه جست‌وجوی «${esc(q)}»</p>`:''}<div class="catalog-toolbar"><span>${fa(list.length)} مدل ${isFavorites?'نشان‌شده':'برای کشف کردن'}</span><div class="filters"><label>رنگ <select data-filter="color" aria-label="فیلتر رنگ">${[['','همه رنگ‌ها'],['light','رنگ‌های روشن'],...Object.entries(colors).map(([k,v])=>[k,v.name])].map(([v,t])=>`<option value="${v}" ${v===color?'selected':''}>${t}</option>`).join('')}</select></label><label>سایز <select data-filter="size" aria-label="فیلتر سایز">${['','S','M','L','XL','XXL'].map(s=>`<option value="${s}" ${s===size?'selected':''}>${s||'همه'}</option>`).join('')}</select></label><label>ترتیب <select data-filter="sort" aria-label="مرتب‌سازی">${[['featured','منتخب dp'],['low','قیمت: کم به زیاد'],['high','قیمت: زیاد به کم']].map(([v,t])=>`<option value="${v}" ${v===sort?'selected':''}>${t}</option>`).join('')}</select></label></div></div>${type||color||size||q?`<p class="search-query"><a class="text-link" href="#/${isFavorites?'favorites':'shop'}${col?'?collection='+col:''}">پاک کردن فیلترها <span>×</span></a></p>`:''}${list.length?`<div class="product-grid catalog-grid">${!isFavorites&&!type&&!color&&!size&&!q&&sort==='featured'?catalogEditorial(col):''}${list.map((p,i)=>card(p)+(i===3&&!isFavorites&&!type&&!color&&!size&&!q&&sort==='featured'&&list.length>6?`<article class="catalog-detail-note">${image('detail','مطالعه تصویری جزئیات یخن')}<div><span class="eyebrow">A CLOSER LOOK</span><h2>جزئیاتی برای نزدیک‌تر دیدن.</h2>${link('#/article/yakhan','روایت یخن')}</div></article>`:'')).join('')}</div>`:empty(isFavorites?'هنوز مدلی نشان نکرده‌اید.':'مدلی با این انتخاب پیدا نشد.','با تغییر فیلترها یا دیدن همه مدل‌ها، انتخاب را ادامه دهید.')}<p class="sample-label" style="margin-top:35px">همه قیمت‌ها و مدل‌ها نمونه‌اند؛ تصاویر مفهومی هستند.</p></section>`}
function empty(title,text){return `<div class="empty-state"><h2>${title}</h2><p>${text}</p><a href="#/shop" class="primary-button">دیدن همه مدل‌ها <span>←</span></a></div>`}
const sizeTable=()=>`<table class="size-table"><caption>جدول نمونه اندازه لباس — سانتی‌متر</caption><thead><tr><th scope="col">سایز</th><th scope="col">دور سینه لباس</th><th scope="col">قد پیراهن</th><th scope="col">سرشانه</th></tr></thead><tbody>${[['S',100,100,44],['M',106,104,46],['L',112,108,48],['XL',118,112,50],['XXL',124,116,52]].map(r=>`<tr><th scope="row" dir="ltr">${r[0]}</th>${r.slice(1).map(v=>`<td>${fa(v)}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="dialog-note">اندازه‌ها صرفاً برای آزمایش پروتوتایپ‌اند. پیش از فروش واقعی باید با اندازه همان مدل جایگزین شوند. دور سینه لباس با دور سینه بدن متفاوت است.</p>`;
function detail(id){const p=product(id);if(!p)return notFound();selection={id:p.id,size:'',qty:1};const c={...colors[p.color],image:p.image||colors[p.color].image};return `<section class="product-page">${crumbs(p.name)}<div class="product-layout"><div class="product-gallery"><div class="gallery-thumbs">
<button class="active" data-action="gallery" data-view="packshot" data-img="${productImage(p)}" aria-label="دیدن عکس خود محصول" aria-pressed="true">${image(productImage(p),'عکس خود '+p.name)}</button>
<button data-action="gallery" data-view="model" data-img="${c.image}" aria-label="دیدن تن‌خور" aria-pressed="false">${image(c.image,'تن‌خور '+p.name)}</button>
<button data-action="gallery" data-view="zoom" data-img="${c.image}" aria-label="بزرگ‌نمایی یخن" aria-pressed="false">${image(c.image,'نمای نزدیک یخن')}</button>
</div><div class="gallery-main packshot" id="gallery-main">${image(productImage(p),'عکس خود '+p.name,'',true)}<span class="gallery-label">تصویر مفهومی · ${c.name}</span></div></div><div class="product-summary"><div class="product-identity"><span class="eyebrow">${collections[p.collections[0]].en}</span><h1>${p.name}</h1><p class="product-subtitle">${p.subtitle} &nbsp; / &nbsp; <bdi>${p.id.replace("NY-","DP-")}</bdi></p><p class="detail-price">${money(p.price)}</p><p class="sample-label">قیمت نمونه · هر دست شامل پیراهن و تنبان در این پروتوتایپ</p></div><p class="product-intro">${p.description}</p><div class="option-group"><div class="option-heading"><span>رنگ: ${c.name}</span></div><div class="color-options"><button class="color-choice active" type="button" aria-pressed="true"><i class="swatch" style="background:${c.hex}"></i>${c.name}</button></div><p class="sample-label" style="margin:8px 0 0">برای رنگ دیگر، مدل‌های مرتبط پایین صفحه را ببینید.</p></div><div class="option-group"><div class="option-heading"><span>سایز خود را انتخاب کنید</span><button data-action="size-guide">راهنمای اندازه‌ها</button></div><div class="size-options">${['S','M','L','XL','XXL'].map(s=>`<button class="size-choice" data-action="size" data-size="${s}" ${!p.sizes.includes(s)?'disabled title="در نمونه موجود نیست"':''} aria-pressed="false" aria-label="سایز ${s}${!p.sizes.includes(s)?'، ناموجود':''}">${s}</button>`).join('')}</div><p class="option-error" id="size-error" role="alert"></p></div><div class="purchase-row"><div class="quantity-control"><button data-action="detail-qty" data-delta="-1" aria-label="کاهش تعداد">−</button><span id="detail-qty">۱</span><button data-action="detail-qty" data-delta="1" aria-label="افزایش تعداد">+</button></div><button class="primary-button" data-action="add-cart" data-id="${p.id}">افزودن به سفارش <span>←</span></button></div>${p.id==='NY-101'?'<a class="passport-product-link" href="#/verify?code=DP-7K4M-92QX">مشاهده شناسنامه یک دست نمونه از این مدل ↗</a>':''}<p class="purchase-note">بدون پرداخت در این مرحله؛ موجودی و جزئیات با فروشنده تأیید می‌شود.</p><details open><summary>مشخصات این طرح مفهومی</summary><dl class="spec-list"><dt>رنگ</dt><dd>${c.name}</dd><dt>نوع یخن</dt><dd>نقش هندسی، دوخت ماشینی</dd><dt>ترکیب پارچه</dt><dd>برای کالای واقعی تعیین نشده</dd><dt>کاربرد پیشنهادی نمونه</dt><dd>${p.type==='ceremony'?'مراسم و مناسبت':'پوشش روزمره'}</dd></dl></details><details><summary>ثبت درخواست و هماهنگی</summary><p>پس از انتخاب، درخواست شما برای بررسی موجودی و هماهنگی هزینه، پرداخت و تحویل ثبت می‌شود. در نسخه فعلی این فرایند فقط شبیه‌سازی می‌شود.</p></details><details><summary>ارسال، نگهداری و تعویض</summary><p>محدوده ارسال و شرایط تعویض فروشگاه هنوز مشخص نشده‌اند. دستور نگهداری باید متناسب با پارچه واقعی اعلام شود. اطلاعات نمونه جایگزین تأیید فروشنده نیست.</p></details><p class="demo-notice" style="margin-top:20px">این مدل و تصویر، نمونه مفهومی برای تجربه طراحی dp هستند.</p></div></div></section><section class="section" style="padding-top:20px"><div class="section-heading"><div><span class="section-kicker">در ادامه انتخاب شما</span><h2>روایت‌های نزدیک</h2></div>${link('#/shop','همه مدل‌ها')}</div><div class="product-grid">${products.filter(x=>x.id!==id).slice(0,4).map(card).join('')}</div></section>`}
function summary(checkout=false){const total=cart.reduce((s,x)=>s+product(x.id).price*x.qty,0);return `<aside class="order-summary"><h2>خلاصه انتخاب شما</h2>${checkout?cart.map(x=>`<div class="mini-order-item">${image(productImage(product(x.id)),product(x.id).name)}<div><h3>${product(x.id).name}</h3><p>${colors[x.color].name} · <bdi>${x.size}</bdi> · ${fa(x.qty)} عدد</p><p>${money(product(x.id).price*x.qty)}</p></div></div>`).join(''):''}<div class="cost-row" style="margin-top:22px"><span>تعداد کالا</span><span>${fa(cart.reduce((s,x)=>s+x.qty,0))}</span></div><div class="cost-row"><span>هزینه ارسال</span><span>پس از بررسی مقصد</span></div><div class="cost-row total"><span>جمع کالاها</span><span>${money(total)}</span></div><p>مبلغ نهایی شامل ارسال، پیش از تأیید سفارش با شما هماهنگ می‌شود.</p>${!checkout?'<a class="primary-button" href="#/checkout">ادامه و ثبت اطلاعات تماس ←</a>':''}<p>قیمت‌ها نمونه‌اند. پرداخت اینترنتی یا سفارش واقعی در این نسخه انجام نمی‌شود.</p></aside>`}
function cartPage(){return `<section class="order-page">${crumbs('خلاصه سفارش')}<h1>انتخاب‌های شما</h1>${!cart.length?empty('هنوز انتخابی به سفارش اضافه نشده.','مجموعه‌ها را ببینید و مدلی که به شما می‌آید انتخاب کنید.'):`<div class="order-layout"><div>${cart.map((x,i)=>{const p=product(x.id);return `<article class="cart-item"><a href="#/product/${p.id}">${image(productImage(p),p.name)}</a><div><a href="#/product/${p.id}"><h2>${p.name}</h2></a><p>${colors[x.color].name} · سایز <bdi>${x.size}</bdi></p><p>قیمت واحد: ${money(p.price)}</p><div class="cart-item-bottom"><div class="quantity-control"><button data-action="cart-qty" data-index="${i}" data-delta="-1" aria-label="کاهش تعداد ${p.name}" ${x.qty===1?'disabled':''}>−</button><span>${fa(x.qty)}</span><button data-action="cart-qty" data-index="${i}" data-delta="1" aria-label="افزایش تعداد ${p.name}" ${x.qty===10?'disabled':''}>+</button></div><span>${money(p.price*x.qty)}</span><button class="remove-item" data-action="remove" data-index="${i}">حذف</button></div></div></article>`}).join('')}${link('#/shop','ادامه دیدن مجموعه‌ها')}</div>${summary()}</div>`}</section>`}
function checkout(){if(!cart.length)return `<section class="order-page">${empty('برای ثبت درخواست، ابتدا یک مدل انتخاب کنید.','هنوز کالایی در سفارش شما نیست.')}</section>`;return `<section class="order-page">${crumbs('ثبت درخواست')}<div class="checkout-steps"><a href="#/cart">۱. انتخاب‌های شما</a><span>←</span><span class="active">۲. اطلاعات تماس و بازبینی</span><span>←</span><span>۳. دریافت درخواست</span></div><h1>یک قدم تا ثبت درخواست</h1>${demo}<div class="order-layout"><form id="checkout-form" novalidate><div class="form-grid"><label class="field">نام و نام خانوادگی <input name="name" autocomplete="name" maxlength="70" value="${esc(draft.name)}" aria-describedby="error-name"><span class="field-error" id="error-name"></span></label><label class="field">شماره تماس <input name="phone" type="tel" inputmode="tel" autocomplete="tel" dir="ltr" placeholder="شماره آزمایشی وارد کنید" maxlength="25" value="${esc(draft.phone)}" aria-describedby="error-phone"><span class="field-error" id="error-phone"></span></label><label class="field">شهر یا ولایت <input name="city" autocomplete="address-level1" maxlength="60" value="${esc(draft.city)}" aria-describedby="error-city"><span class="field-error" id="error-city"></span></label><label class="field">روش ترجیحی هماهنگی <select name="channel"><option value="call" ${draft.channel!=='message'?'selected':''}>تماس تلفنی — سناریوی نمونه</option><option value="message" ${draft.channel==='message'?'selected':''}>پیام — سناریوی نمونه</option></select></label><label class="field full">یادداشت برای فروشگاه <textarea name="note" rows="3" maxlength="500" placeholder="مثلاً برای انتخاب سایز به راهنمایی نیاز دارم">${esc(draft.note)}</textarea><small>اختیاری · نشانی کامل برای این درخواست نمایشی لازم نیست.</small></label></div><label class="form-check"><input type="checkbox" name="consent" ${draft.consent?'checked':''}><span>می‌دانم این درخواست آزمایشی است، پرداختی انجام نمی‌شود و اطلاعات برای فروشگاه ارسال نخواهد شد.</span></label><p class="field-error" id="error-consent" role="alert"></p><div class="demo-notice">در تجربه واقعی، فروشنده موجودی، سایز، مبلغ نهایی و شیوه تحویل را پیش از قطعی شدن با شما هماهنگ می‌کند. ثبت درخواست به معنی تأیید سفارش نیست.</div><div class="form-actions"><button class="primary-button" type="submit">ثبت درخواست آزمایشی ←</button><p>از اطلاعات واقعی استفاده نکنید. داده آزمایشی فقط در همین مرورگر باقی می‌ماند.</p></div><p class="field-error" id="checkout-error" role="alert"></p></form>${summary(true)}</div></section>`}
function receipt(id){const o=orders.find(x=>x.id===id);if(!o)return notFound();return `<section class="receipt"><div class="receipt-symbol" aria-hidden="true">✓</div><span class="eyebrow">YOUR SELECTION, RECEIVED</span><h1>درخواست شما دریافت شد.</h1><p>${esc(o.customer.name)}، انتخاب شما در این مرورگر ثبت شد. این یک درخواست آزمایشی است و برای فروشگاه ارسال نشده است.</p><div class="receipt-code"><span>کد درخواست نمایشی</span><strong dir="ltr">${o.id}</strong></div><div class="status-badge">${statusText(o.status)}</div><p>این رسید به معنی تأیید موجودی، نهایی شدن سفارش یا پرداخت نیست.</p>${orderItems(o)}<div class="receipt-actions"><a class="primary-button" href="#/track?code=${o.id}">دیدن وضعیت درخواست ←</a><a class="secondary-button" href="#/shop">بازگشت به مجموعه‌ها</a></div></section>`}
const statusLabels={received:'دریافت شد؛ در انتظار بررسی',reviewing:'در حال بررسی فروشگاه',awaiting:'منتظر موافقت شما',confirmed:'تأییدشده — شبیه‌سازی',preparing:'در حال آماده‌سازی — شبیه‌سازی',shipped:'ارسال‌شده — شبیه‌سازی',delivered:'تحویل‌شده — شبیه‌سازی',cancelled:'درخواست لغو شد',unavailable:'ناموجود؛ نیازمند انتخاب جایگزین'};
function statusText(s){return statusLabels[s]||statusLabels.received}
function orderItems(o){return `<div style="margin-top:25px">${o.items.map(x=>`<div class="mini-order-item">${image(productImage(product(x.id)),x.name)}<div><h3>${esc(x.name)}</h3><p>${colors[x.color].name} · سایز <bdi>${esc(x.size)}</bdi> · ${fa(x.qty)} عدد</p><p>${money(x.price*x.qty)}</p></div></div>`).join('')}<div class="cost-row" style="margin-top:20px"><span>جمع کالاها</span><span>${money(o.total)}</span></div><p class="purchase-note">هزینه ارسال و روش پرداخت: ${['received','reviewing','unavailable'].includes(o.status)?'هنوز تعیین نشده':'طبق توافق فرضی سناریو؛ بدون تراکنش واقعی'}</p></div>`}
function tracking(params){const code=(params.get('code')||'').toUpperCase();const o=orders.find(x=>x.id===code);const stages=['received','reviewing','awaiting','confirmed','preparing','shipped','delivered'];return `<section class="content-page"><span class="eyebrow">WITH YOU, STEP BY STEP</span><h1>همراه درخواست شما</h1><p>کد دریافت‌شده را وارد کنید تا وضعیت درخواست آزمایشی همین مرورگر را ببینید.</p><form class="track-form" id="track-form"><label class="field">کد درخواست<input name="code" dir="ltr" maxlength="35" required placeholder="NY-…" value="${esc(code)}"></label><button class="primary-button" type="submit">بررسی وضعیت ←</button></form>${code&&!o?'<div class="demo-notice" role="alert">درخواستی با این کد در این مرورگر پیدا نشد. کد را از رسید کپی کنید؛ درخواست‌های این نمونه به سرور ارسال نمی‌شوند.</div>':''}${o?`<div class="receipt-code"><span>درخواست آزمایشی</span><strong dir="ltr">${o.id}</strong></div><div class="status-badge">${statusText(o.status)}</div>${['cancelled','unavailable'].includes(o.status)?`<p>${o.status==='cancelled'?'این درخواست لغو شده و ادامه پیدا نمی‌کند.':'این سناریو، ناموجودی کالا و نیاز به هماهنگی برای جایگزین را نشان می‌دهد.'}</p>`:`<ol class="status-list">${stages.map((s,i)=>`<li class="${i===stages.indexOf(o.status)?'current':i<stages.indexOf(o.status)?'done':''}"><h3>${statusText(s)}</h3><p>${['انتخاب شما ثبت شده؛ هنوز سفارش قطعی نیست.','بررسی موجودی، سایز و امکان تحویل.','بازبینی و موافقت با جزئیات نهایی.','سفارش با موافقت دو طرف نهایی می‌شود.','آماده‌سازی طبق توافق.','اطلاع‌رسانی تحویل به حامل، در صورت پشتیبانی.','پایان مسیر و امکان طرح مشکل طبق شرایط فروشگاه.'][i]}</p></li>`).join('')}</ol>`}${orderItems(o)}${o.status==='awaiting'?`<div class="demo-notice" style="margin-top:25px">توافق فرضی: همان جمع کالاها؛ تحویل حضوری و روش پرداخت با هماهنگی فروشنده. این سناریو تعهد واقعی ایجاد نمی‌کند.</div><button class="primary-button" data-action="accept-order" data-id="${o.id}">موافقت با سناریوی نمونه</button>`:''}${['received','reviewing','awaiting'].includes(o.status)?`<button class="secondary-button" style="margin:15px" data-action="cancel-order" data-id="${o.id}">لغو درخواست آزمایشی</button>`:''}<div class="demo-controls"><h3>آزمایش سمت فروشگاه</h3><p>این کنترل فقط برای تجربه پروتوتایپ است. با تغییر وضعیت، رفتار پیگیری مشتری را ببینید؛ هیچ پیام یا سفارش واقعی ایجاد نمی‌شود.</p><label class="field">تغییر وضعیت نمایشی<select data-demo-order="${o.id}">${Object.entries(statusLabels).filter(([s])=>s!=='confirmed').map(([s,t])=>`<option value="${s}" ${o.status===s?'selected':''}>${t}</option>`).join('')}${o.status==='confirmed'?'<option value="confirmed" selected>تأییدشده — شبیه‌سازی</option>':''}</select></label></div>`:orders.length?`<div><h2>درخواست‌های آزمایشی این نشست</h2>${orders.map(x=>`<p><a class="text-link" href="#/track?code=${x.id}"><bdi>${x.id}</bdi><span>←</span></a></p>`).join('')}</div>`:''}</section>`}
function guide(params){const tab=params.get('tab')||'size';return `<section class="content-page">${crumbs('راهنمای انتخاب و سفارش')}<span class="eyebrow">A MORE CONSIDERED CHOICE</span><h1>با اطمینان انتخاب کنید.</h1><nav class="guide-tabs" aria-label="موضوعات راهنما">${[['size','اندازه و سایز'],['order','روش سفارش'],['delivery','ارسال و تعویض']].map(([v,t])=>`<a class="${tab===v?'active':''}" href="#/guide?tab=${v}">${t}</a>`).join('')}</nav>${tab==='order'?`<h2>انتخاب آنلاین، هماهنگی با فروشنده</h2><p>مدل، رنگ و سایز را انتخاب کنید. در خلاصه سفارش می‌توانید تعداد یا انتخابتان را اصلاح کنید. سپس اطلاعات تماس را برای بررسی درخواست ثبت می‌کنید.</p><div class="steps"><article><strong>01</strong><h3>انتخاب و بازبینی</h3><p>قیمت واحد، تعداد و جمع کالاها را ببینید. هزینه ارسال نامشخص، صفر محسوب نمی‌شود.</p></article><article><strong>02</strong><h3>ثبت درخواست</h3><p>ثبت درخواست با تأیید سفارش متفاوت است. در این مرحله پرداختی صورت نمی‌گیرد.</p></article><article><strong>03</strong><h3>توافق و تأیید</h3><p>موجودی، مبلغ نهایی، روش پرداخت و تحویل پیش از قطعی شدن هماهنگ می‌شوند.</p></article></div>${demo}<a class="primary-button" href="#/shop">شروع انتخاب ←</a>`:tab==='delivery'?`<h2>پیش از تأیید، همه‌چیز روشن می‌شود.</h2><p>محدوده ارسال، هزینه حمل و زمان تحویل dp هنوز در این نمونه تعیین نشده‌اند. پیش از سفارش واقعی، فروشگاه باید پوشش مقصد، مبلغ نهایی و بازه تحویل را مشخص کند.</p><h2>تعویض و رسیدگی به مشکل</h2><p>مدت و شرایط تعویض، وضعیت کالای قابل پذیرش و مسئولیت هزینه رفت‌وبرگشت باید پیش از تأیید سفارش اعلام شوند. این پروتوتایپ سیاست واقعی فروشگاه را جعل نمی‌کند.</p><h2>پرداخت چگونه انجام می‌شود؟</h2><p>روش پرداخت با توجه به امکانات واقعی فروشگاه و مقصد تعیین می‌شود. پرداخت هنگام تحویل، پیش‌پرداخت یا ارسال بین‌المللی در این نسخه وعده داده نمی‌شوند.</p>${demo}`:`<h2>اندازه لباس، نقطه شروع انتخاب</h2><p>یک پیراهن‌تنبان با تن‌خور مناسب را صاف روی سطح قرار دهید. عرض سینه را از زیر بغل تا زیر بغل، سرشانه را بین دو درز و قد را از بالای شانه تا پایین پیراهن اندازه بگیرید. در این جدول، دور سینه لباس دو برابر عرض سینه در حالت صاف است.</p>${sizeTable()}<h2>بین دو سایز هستید؟</h2><p>فرم برش و آزادی دلخواه مهم‌اند. به‌جای حدس، در یادداشت درخواست بنویسید که راهنمایی سایز می‌خواهید. اندازه‌های واقعی هر مدل باید با فروشنده تأیید شوند.</p>${link('#/article/fit','خواندن راهنمای تن‌خور')}`}</section>`}
function about(){return `<section class="section"><div class="story-layout"><div><span class="eyebrow">THE WORLD OF dp</span><h1>پوششی آشنا،<br>نگاهی تازه.</h1><p>dp، فروشگاهی برای پیراهن‌تنبان مردانه است؛ با پشتوانه فروش حضوری و تمرکز بر تولید با دستگاه‌های مدرن. اینجا، جهان تازه برند را از فرم لباس، ظرافت یخن و تجربه انتخاب روایت می‌کنیم.</p><p style="margin-top:18px">برای ما، طراحی خوب باید به دیدن دقیق‌تر کمک کند؛ تا پیش از انتخاب، رنگ، نقش و فرم لباس را بهتر بشناسید.</p>${link('#/shop','کشف مجموعه‌ها')}</div>${image('ivory','تن‌خور مفهومی پیراهن‌تنبان dp')}</div></section><section class="content-page about-detail"><span class="eyebrow">ROOTED IN DETAIL</span><h2>اصالت را از خود لباس می‌گیریم.</h2><p>هندسه یخن، امتداد دوخت و تناسب فرم، نقطه شروع هویت بصری dp‌اند. روایت برند بر کیفیت قابل بررسی محصول تکیه می‌کند؛ مشخصات پارچه و فرایند تولید هر مدل باید پیش از فروش واقعی تکمیل شوند.</p><div class="steps"><article><strong>01</strong><h3>دیدن از نزدیک</h3><p>تصویر کلی و جزئیات، کنار هم به انتخاب شما کمک می‌کنند.</p></article><article><strong>02</strong><h3>انتخاب روشن</h3><p>اندازه، رنگ و قیمت باید پیش از ثبت درخواست قابل فهم باشند.</p></article><article><strong>03</strong><h3>گفت‌وگوی مستقیم</h3><p>سفارش با بررسی موجودی و هماهنگی نهایی فروشنده ادامه پیدا می‌کند.</p></article></div>${demo}</section>${services()}`}
function journal(){return `<section class="page-head">${crumbs('مجله dp')}<span class="eyebrow">STORIES, DETAILS & EVERYDAY ELEGANCE</span><h1>روایت‌هایی برای نزدیک‌تر دیدن</h1><p>از زبان نقش تا انتخاب اندازه؛ یادداشت‌هایی در جهان پوشش dp.</p></section><section class="section journal"><div class="journal-heading">dp JOURNAL</div><div class="article-grid">${articles.map(articleCard).join('')}</div></section>`}
function articlePage(id){const a=articles.find(x=>x.id===id);if(!a)return notFound();return `<section class="content-page"><article class="article-body">${crumbs('مجله / '+a.category)}<p class="article-meta">مجله dp · ${a.category} · ${a.time} مطالعه</p><h1>${a.title}</h1>${image(a.image,a.title,'wide-image',true)}<p>${a.intro}</p>${a.sections.map(([h,p])=>`<h2>${h}</h2><p>${p}</p>`).join('')}<p class="demo-notice">محتوای تحریریه نمونه و تصاویر مفهومی برای پروتوتایپ dp.</p>${link('#/journal','بازگشت به مجله')}</article></section>`}
function contact(){return `<section class="content-page">${crumbs('ارتباط با dp')}<span class="eyebrow">LET’S TALK, IN PERSON</span><h1>از نزدیک آشنا شویم.</h1><p>فروشگاه حضوری، بخشی از تجربه dp است. اطلاعات دقیق ارتباط و مراجعه، پیش از راه‌اندازی واقعی در این صفحه قرار می‌گیرند.</p><div class="contact-grid"><div class="contact-panel"><h2>فروشگاه dp</h2><dl class="contact-list"><dt>نشانی فروشگاه</dt><dd>پس از تأیید برند درج می‌شود.</dd><dt>تلفن و کانال ارتباطی</dt><dd>در این پروتوتایپ اطلاعات تماس واقعی تعریف نشده است.</dd><dt>ساعات مراجعه</dt><dd>در انتظار اعلام فروشگاه.</dd></dl><p>برای جلوگیری از تماس اشتباه، شماره و نشانی ساختگی نمایش داده نمی‌شود.</p></div><div><h2>به چه راهنمایی نیاز دارید؟</h2><p>برای آشنایی با مسیر درخواست و انتخاب اندازه، راهنماها در دسترس شما هستند.</p><p>${link('#/guide','راهنمای سایز')}</p><p>${link('#/guide?tab=order','روش ثبت درخواست')}</p><p>${link('#/track','پیگیری درخواست آزمایشی')}</p></div></div></section>`}

// One physical unit for this prototype, independent of the model/SKU.
const demoPassport=Object.freeze({serial:'DP-7K4M-92QX',productId:'NY-101',size:'M',batch:'DP-26-01'});
function normalizePassport(value){return normalize(value).toUpperCase().replace(/[‐‑–—−]/g,'')}
function passportPage(params){
 const entered=params.get('code')||'';
 const attempted=params.has('code');
 const found=attempted&&normalizePassport(entered)===normalizePassport(demoPassport.serial);
 const p=product(demoPassport.productId);
 return `<section class="passport-page">${crumbs('استعلام محصول')}<div class="passport-heading"><span class="eyebrow">THE dp PASSPORT</span><h1>${found?'شناسنامه این لباس.':attempted&&entered.trim()?'نتیجه استعلام محصول.':'داستان این لباس،<br>در شناسنامه‌اش.'}</h1><p>${found?'مشخصات ثبت‌شده این لباس را ببینید و با برچسب و جزئیات آن تطبیق دهید.':'شناسه روی برچسب لباس را وارد کنید؛ یا QR آن را با دوربین گوشی اسکن کنید تا مستقیم به شناسنامه برسید.'}</p><span class="passport-demo">نسخه نمایشی · یک شناسنامه نمونه</span></div><div class="passport-layout ${attempted&&entered.trim()?'has-result':''}"><div class="passport-entry"><h2>استعلام محصول</h2><form id="passport-form" novalidate><label for="passport-code">شناسه یکتای لباس</label><input id="passport-code" name="code" dir="ltr" autocomplete="off" autocapitalize="characters" spellcheck="false" maxlength="64" placeholder="DP-XXXX-XXXX" value="${esc(entered)}" aria-describedby="passport-help passport-error" ${attempted&&!found?'aria-invalid="true"':''}><p id="passport-help">این شناسه مخصوص یک دست لباس است و با کد مدل تفاوت دارد.</p><p id="passport-error" class="field-error" role="alert">${attempted&&!entered.trim()?'شناسه لباس را وارد کنید.':''}</p><button class="primary-button" type="submit">مشاهده شناسنامه <span>←</span></button></form><div class="passport-sample"><span class="eyebrow">TRY THE EXPERIENCE</span><h3>یک شناسنامه را امتحان کنید.</h3><a class="passport-sample-code" href="#/verify?code=${demoPassport.serial}"><bdi>${demoPassport.serial}</bdi><span>مشاهده نمونه ↗</span></a><div class="passport-qr-row"><div id="passport-qr" aria-label="QR شناسنامه نمونه"></div><p>با دوربین گوشی اسکن کنید.<small>در اجرای محلی، گوشی باید به نشانی این سایت دسترسی داشته باشد.</small></p></div></div></div><div class="passport-result" id="passport-result" aria-live="polite">${found?`<div class="passport-status"><span aria-hidden="true">✓</span><div><span class="eyebrow">REGISTERED PRODUCT · DEMO</span><h2>شناسنامه ثبت‌شده در dp</h2></div></div><div class="passport-document"><a class="passport-photo" href="#/product/${p.id}">${image(productImage(p),p.name,'',true)}</a><div class="passport-document-info"><span class="eyebrow">PRODUCT PASSPORT / 001</span><h3>${p.name}</h3><p>${p.subtitle}</p><dl><dt>شناسه یکتای این لباس</dt><dd><bdi>${demoPassport.serial}</bdi></dd><dt>کد مدل</dt><dd><bdi>DP-101</bdi></dd><dt>رنگ</dt><dd>${colors[p.color].name}</dd><dt>سایز</dt><dd><bdi>${demoPassport.size}</bdi></dd><dt>سری تولید نمونه</dt><dd><bdi>${demoPassport.batch}</bdi></dd></dl>${link('#/product/'+p.id,'دیدن مدل و جزئیات')}</div></div><p class="passport-footnote">تصویر و مشخصات را با لباس خود تطبیق دهید. ثبت این شناسه، به‌تنهایی اصالت لباس فیزیکی را تضمین نمی‌کند.</p><p class="sample-label">این شناسنامه و اطلاعات آن آزمایشی‌اند.</p>`:attempted&&entered.trim()?`<div class="passport-message"><span class="eyebrow">NO RECORD FOUND</span><h2>محصولی با این شناسه در سیستم dp پیدا نشد.</h2><p>شناسه <bdi>${esc(entered)}</bdi> را با برچسب لباس تطبیق دهید و دوباره امتحان کنید.</p><p>پیدا نشدن شناسه به‌تنهایی به معنی تقلبی بودن لباس نیست. برای بررسی بیشتر با فروشگاه در ارتباط باشید.</p>${link('#/contact','ارتباط با فروشگاه')}</div>`:`<div class="passport-waiting"><span class="passport-seal" aria-hidden="true">dp</span><span class="eyebrow">A GARMENT. AN IDENTITY.</span><h2>جزئیات، به نام همین لباس.</h2><p>پس از وارد کردن شناسه، عکس، مدل، رنگ و سایز ثبت‌شده را اینجا می‌بینید.</p></div>`}</div></div></section>`;
}
function renderPassportQR(){const holder=document.getElementById('passport-qr');if(!holder)return;const url=new URL(location.href);url.search='';url.hash='/verify?code='+demoPassport.serial;const qr=qrcode(0,'M');qr.addData(url.href);qr.make();holder.innerHTML=qr.createSvgTag({cellSize:3,margin:12,scalable:true});holder.querySelector('svg').setAttribute('aria-hidden','true')}

function notFound(){return `<section class="content-page">${empty('این صفحه پیدا نشد.','می‌توانید از مجموعه‌های dp، دوباره شروع کنید.')}</section>`}
function updateBag(){const n=cart.reduce((s,x)=>s+x.qty,0);const b=document.getElementById('bag-count');b.textContent=fa(n);b.hidden=!n;document.querySelector('.bag-link').setAttribute('aria-label','خلاصه سفارش؛ '+fa(n)+' کالا');write('nayab-cart-v1',cart)}
function route(){if(submitting)return;if(location.hash==='#main')return;closeDialog();const raw=location.hash.startsWith('#/')?location.hash.slice(1):'/';const [path,query='']=raw.split('?');const params=new URLSearchParams(query);const parts=path.split('/').filter(Boolean);const key=parts[0]||'home';let html;switch(key){case 'home':html=home();break;case 'shop':html=shop(params);break;case 'favorites':html=shop(params,true);break;case 'product':html=detail(parts[1]);break;case 'cart':html=cartPage();break;case 'checkout':html=checkout();break;case 'receipt':html=receipt(parts[1]);break;case 'track':html=tracking(params);break;case 'verify':html=passportPage(params);break;case 'guide':html=guide(params);break;case 'about':html=about();break;case 'contact':html=contact();break;case 'journal':html=journal();break;case 'article':html=articlePage(parts[1]);break;default:html=notFound();}
main.innerHTML=html;renderPassportQR();document.title=(main.querySelector('h1')?.textContent||'وقار، در جزئیات')+' | dp';updateBag();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}
function notify(text,cartLink=false){const toast=document.getElementById('toast');toast.innerHTML=esc(text)+(cartLink?'<a href="#/cart">دیدن سفارش ←</a>':'');toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),4500)}
function dialog(title,content){previousFocus=document.activeElement;overlay.innerHTML=`<div class="dialog-top"><h2 id="dialog-title">${title}</h2><button class="dialog-close" data-action="close" aria-label="بستن پنجره">×</button></div>${content}`;overlay.showModal();document.body.classList.add('modal-open');overlay.querySelector('input,button')?.focus()}
function closeDialog(){if(overlay.open)overlay.close();document.body.classList.remove('modal-open')}
overlay.addEventListener('close',()=>{document.body.classList.remove('modal-open');if(previousFocus?.isConnected)previousFocus.focus();previousFocus=null});
overlay.addEventListener('click',e=>{if(e.target===overlay){const r=overlay.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
if(action==='menu')dialog('جهان dp',`<nav class="menu-links"><a href="#/">خانه</a><a href="#/shop">همه مدل‌ها و مجموعه‌ها</a><a href="#/about">درباره dp</a><a href="#/journal">مجله dp</a><a href="#/favorites">انتخاب‌های نشان‌شده</a><a href="#/guide">راهنمای سایز و سفارش</a><a href="#/track">پیگیری درخواست</a><a href="#/verify">استعلام محصول</a><a href="#/contact">فروشگاه و ارتباط</a></nav>`);
if(action==='close')closeDialog();
if(action==='toggle-model'){
  const visual=b.closest('.product-visual');
  const showModel=visual.classList.toggle('is-model');
  b.setAttribute('aria-pressed',String(showModel));
  b.querySelector('.switch-label').textContent=showModel?'عکس محصول':'تن‌خور';
  const title=visual.closest('.product-card').querySelector('h3').textContent;
  b.setAttribute('aria-label',(showModel?'دیدن عکس خود ':'دیدن تن‌خور ')+title);
}

if(action==='search'){dialog('در جهان dp جست‌وجو کنید',`<form id="search-form" class="search-form"><input name="q" aria-label="نام مدل، رنگ یا کد محصول" placeholder="نام مدل، رنگ یا کد محصول…" maxlength="80" required><button class="primary-button" type="submit">جست‌وجو ←</button></form><p class="dialog-note">مثلاً «سرو»، «عاجی» یا «DP-101»</p>`);overlay.querySelector('input').focus()}
if(action==='size-guide')dialog('راهنمای اندازه‌ها',sizeTable()+`<p class="dialog-note">اندازه‌ها به سانتی‌متر هستند. یک لباس مناسب را صاف اندازه بگیرید و با جدول مقایسه کنید.</p>`);
if(action==='favorite'){const id=b.dataset.id;if(!product(id))return;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];write('nayab-favorites-v1',favorites);if(location.hash.startsWith('#/favorites')){const y=window.scrollY;route();window.scrollTo(0,y)}else document.querySelectorAll(`[data-action="favorite"][data-id="${id}"]`).forEach(x=>{x.classList.toggle('active',favorites.includes(id));x.setAttribute('aria-pressed',String(favorites.includes(id)))});notify(favorites.includes(id)?'برای دوباره دیدن، نشان شد.':'از انتخاب‌های نشان‌شده حذف شد.')}
if(action==='size'){selection.size=b.dataset.size;document.querySelectorAll('.size-choice').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.getElementById('size-error').textContent=''}
if(action==='detail-qty'){selection.qty=Math.max(1,Math.min(10,selection.qty+Number(b.dataset.delta)));document.getElementById('detail-qty').textContent=fa(selection.qty)}
if(action==='gallery'){document.querySelectorAll('[data-action="gallery"]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});const g=document.getElementById('gallery-main');g.className='gallery-main '+b.dataset.view;g.innerHTML=image(b.dataset.img,b.dataset.view==='packshot'?'عکس خود محصول':b.dataset.view==='zoom'?'بزرگ‌نمایی تصویر مفهومی یخن':'تن‌خور مفهومی لباس')+`<span class="gallery-label">${b.dataset.view==='detail'?'مطالعه مفهومی بافت؛ تصویر همان کالای واقعی نیست':'تصویر مفهومی'}</span>`}
if(action==='add-cart'){const p=product(b.dataset.id);if(!p||!p.sizes.includes(selection.size)){document.getElementById('size-error').textContent='پیش از افزودن، سایز را انتخاب کنید.';document.querySelector('.size-choice:not(:disabled)')?.focus();return}const found=cart.find(x=>x.id===p.id&&x.size===selection.size);if(found){const next=found.qty+selection.qty;if(next>10)notify('حداکثر تعداد هر مدل و سایز در نمونه، ۱۰ عدد است.');found.qty=Math.min(10,next)}else cart.push({id:p.id,color:p.color,size:selection.size,qty:selection.qty});updateBag();notify('به انتخاب‌های شما اضافه شد.',true)}
if(action==='cart-qty'){const item=cart[Number(b.dataset.index)];if(!item)return;item.qty=Math.max(1,Math.min(10,item.qty+Number(b.dataset.delta)));const y=window.scrollY;route();window.scrollTo(0,y)}
if(action==='remove'){cart.splice(Number(b.dataset.index),1);route();notify('از خلاصه سفارش حذف شد.')}
if(action==='cancel-order'){const o=orders.find(x=>x.id===b.dataset.id);if(!o)return;dialog('لغو درخواست آزمایشی',`<p>این درخواست آزمایشی لغو می‌شود و در پیگیری با وضعیت لغوشده باقی می‌ماند.</p><div class="receipt-actions"><button class="primary-button" data-action="confirm-cancel" data-id="${o.id}">لغو درخواست</button><button class="secondary-button" data-action="close">بازگشت</button></div>`)}
if(action==='confirm-cancel'){const o=orders.find(x=>x.id===b.dataset.id);if(o){o.status='cancelled';write('nayab-demo-orders-v1',orders,true);route();notify('درخواست آزمایشی لغو شد.')}}
if(action==='accept-order'){const o=orders.find(x=>x.id===b.dataset.id);if(o?.status==='awaiting'){o.status='confirmed';o.accepted=true;write('nayab-demo-orders-v1',orders,true);route();notify('تأیید سناریوی نمونه ثبت شد؛ پرداختی انجام نشد.')}}
});
document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(a?.classList.contains('skip-link')){e.preventDefault();main.focus();main.scrollIntoView();return}if(a&&overlay.open&&a.hash===location.hash)closeDialog()});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.filter){const [base,qs='']=location.hash.split('?');const p=new URLSearchParams(qs);if(t.value)p.set(t.dataset.filter,t.value);else p.delete(t.dataset.filter);location.hash=base+(p.size?'?'+p.toString():'')}
if(t.dataset.demoOrder){const o=orders.find(x=>x.id===t.dataset.demoOrder);if(o&&Object.hasOwn(statusLabels,t.value)){o.status=t.value;write('nayab-demo-orders-v1',orders,true);const y=window.scrollY;route();window.scrollTo(0,y);notify('وضعیت نمایشی تغییر کرد.')}}});
function saveDraft(form){draft=Object.fromEntries(new FormData(form));draft.consent=form.elements.consent.checked;write('nayab-demo-draft-v1',draft,true)}
document.addEventListener('input',e=>{const form=e.target.closest('#checkout-form');if(form)saveDraft(form)});
document.addEventListener('change',e=>{const form=e.target.closest('#checkout-form');if(form)saveDraft(form)});
document.addEventListener('submit',async e=>{const f=e.target;if(f.id==='search-form'){e.preventDefault();const q=f.elements.q.value.trim();if(q){closeDialog();const target='#/shop?q='+encodeURIComponent(q);if(location.hash===target)route();else location.hash=target}return}
if(f.id==='passport-form'){e.preventDefault();const code=f.elements.code.value.trim();if(!code){document.getElementById('passport-error').textContent='شناسه لباس را وارد کنید.';f.elements.code.setAttribute('aria-invalid','true');f.elements.code.focus();return}const target='#/verify?code='+encodeURIComponent(code);if(location.hash===target)route();else location.hash=target;return}
if(f.id==='track-form'){e.preventDefault();const code=f.elements.code.value.trim().toUpperCase();const target='#/track?code='+encodeURIComponent(code);if(location.hash===target)route();else location.hash=target;return}
if(f.id!=='checkout-form')return;e.preventDefault();if(submitting)return;saveDraft(f);const phone=normalize(f.elements.phone.value);const errors={name:f.elements.name.value.trim().length<2?'نام را با حداقل دو حرف وارد کنید.':'',phone:!/^\+?\d{8,15}$/.test(phone)?'شماره آزمایشی معتبر با ۸ تا ۱۵ رقم وارد کنید.':'',city:f.elements.city.value.trim().length<2?'شهر یا ولایت را وارد کنید.':'',consent:!f.elements.consent.checked?'برای ادامه، آزمایشی بودن درخواست را تأیید کنید.':''};for(const [name,error]of Object.entries(errors)){document.getElementById('error-'+name).textContent=error;f.elements[name].setAttribute('aria-invalid',String(!!error))}const first=Object.keys(errors).find(k=>errors[k]);if(first){f.elements[first].focus();return}if(!cart.length){document.getElementById('checkout-error').textContent='سبد شما خالی است. ابتدا یک مدل انتخاب کنید.';return}submitting=true;const button=f.querySelector('[type="submit"]');button.disabled=true;button.textContent='در حال ثبت درخواست آزمایشی…';try{await new Promise(resolve=>setTimeout(resolve,450));const items=cart.map(x=>({...x,name:product(x.id).name,price:product(x.id).price}));const id='DP-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,5).toUpperCase();const o={id,status:'received',created:new Date().toISOString(),customer:{name:f.elements.name.value.trim(),phone,city:f.elements.city.value.trim(),channel:f.elements.channel.value,note:f.elements.note.value.trim()},items,total:items.reduce((s,x)=>s+x.price*x.qty,0)};orders.unshift(o);write('nayab-demo-orders-v1',orders,true);cart=[];draft={};write('nayab-demo-draft-v1',draft,true);updateBag();submitting=false;location.hash='#/receipt/'+id}catch{document.getElementById('checkout-error').textContent='ثبت انجام نشد. انتخاب‌ها حفظ شده‌اند؛ دوباره تلاش کنید.';button.disabled=false;button.textContent='ثبت درخواست آزمایشی ←';submitting=false}});
window.addEventListener('hashchange',route);route();
